/**
 * wasm-load-node.js — Node env shim for the WASM engine.
 *
 * Resolves the wasm-pack --target nodejs artifact at fat/pkg-node/egpt_wasm.js
 * and returns the WasmUniverse constructor so wasm-engine.js can be
 * env-agnostic.
 *
 * The node pkg generated by wasm-pack --target nodejs is SYNCHRONOUS:
 * it reads the .wasm file via readFileSync and instantiates it during
 * require().  There is NO async init() call required.  The WasmUniverse
 * class is exported as exports.WasmUniverse.
 *
 * If the artifact is absent (fat/pkg-node not built), throws a clear error
 * with the build command — never silently returns undefined.
 *
 * Also sets the node globals that game objects expect (Rectangle, random,
 * radians, cos, sin).
 *
 * Path from this file:
 *   frqtl/compat/providers/wasm-load-node.js
 *   → fat/pkg-node/egpt_wasm.js         is  ../../../fat/pkg-node/egpt_wasm.js
 *   → frqtl/objects/geometry/Rectangle.js is ../../objects/geometry/Rectangle.js
 */
(function () {
    'use strict';

    var path = require('path');

    var NODE_PKG_PATH = path.resolve(__dirname, '..', '..', '..', 'fat', 'pkg-node', 'egpt_wasm.js');
    var RECTANGLE_PATH = path.resolve(__dirname, '..', '..', 'objects', 'geometry', 'Rectangle.js');

    /**
     * Load the WASM universe constructor for node.
     *
     * @param {string} [wasmPkgPath] - Optional override for the pkg path.
     * @returns {Promise<{WasmUniverse: Function, Rectangle: Function}>}
     */
    function load(wasmPkgPath) {
        return new Promise(function (resolve, reject) {
            var pkgPath = wasmPkgPath || NODE_PKG_PATH;
            var wasmMod;
            try {
                wasmMod = require(pkgPath);
            } catch (e) {
                var isNotFound = (e.code === 'MODULE_NOT_FOUND');
                if (isNotFound) {
                    return reject(new Error(
                        '[wasm-load-node] WASM node artifact not found at: ' + pkgPath + '\n' +
                        'Build it with:\n' +
                        '  wasm-pack build fat/crates/egpt_wasm --target nodejs --out-dir fat/pkg-node\n' +
                        '(from the FRAQTL repo root)'
                    ));
                }
                return reject(new Error('[wasm-load-node] Failed to load WASM node module: ' + e.message));
            }

            var WasmUniverse = wasmMod.WasmUniverse;
            if (!WasmUniverse) {
                return reject(new Error(
                    '[wasm-load-node] WasmUniverse not found in module at ' + pkgPath +
                    '. Ensure wasm-pack built with --target nodejs.'
                ));
            }

            // ── Set up node globals expected by game layer ───────────────
            var rectangleMod;
            try {
                rectangleMod = require(RECTANGLE_PATH);
            } catch (e) {
                return reject(new Error('[wasm-load-node] Could not load Rectangle: ' + e.message));
            }

            global.Rectangle = rectangleMod.Rectangle;

            if (typeof random === 'undefined') {
                global.random = function (a, b) {
                    if (b === undefined) return (a === undefined ? Math.random() : Math.random() * a);
                    return a + Math.random() * (b - a);
                };
                global.radians = function (deg) { return deg * Math.PI / 180; };
                global.cos = Math.cos;
                global.sin = Math.sin;
            }

            resolve({
                WasmUniverse: WasmUniverse,
                Rectangle: rectangleMod.Rectangle,
            });
        });
    }

    // ── Dual-mode publish ────────────────────────────────────────────────

    if (typeof module !== 'undefined' && module.exports) {
        module.exports = { load: load };
    }
    if (typeof window !== 'undefined') {
        window._WasmLoadNode = { load: load };
    }

})();
